import json
import os
import re
from collections import OrderedDict, defaultdict
from pathlib import Path

from journal_kb.models import SYMBOL

WIKI_KINDS = ("journal", "architecture", "future_log")
STATE_SYMBOL = {"done": "×", "migrated": ">", "scheduled": "<"}
INDEX_START, INDEX_END = "<!-- journal-kb:start -->", "<!-- journal-kb:end -->"
PROJECT_START, PROJECT_END = "<!-- journal-kb:decisions:start -->", "<!-- journal-kb:decisions:end -->"
GENERATED = (
    "> [!info] Generated by journal-kb from the reMarkable journal. Edits here are overwritten on the next "
    "ingest; correct the paper page instead."
)


def format_entry(e: dict, link_projects: bool = True) -> str:
    symbol = SYMBOL[e["bullet"]]
    if e["bullet"] in ("task", "delegated") and e["state"] in STATE_SYMBOL:
        symbol = STATE_SYMBOL[e["state"]]
    marks = ("! " if e["signal"] else "") + ("* " if e["priority"] else "")
    owner = f"{e['owner']} " if e["bullet"] == "delegated" and e["owner"] else ""
    text = f"~~{e['text']}~~" if e["state"] == "dropped" else e["text"]
    line = f"{marks}{symbol} {owner}{text}"
    if e["due"]:
        line += f" (due {e['due']})"
    if e["project"] and link_projects:
        line += f" · [[{e['project']}]]"
    if e["confidence"] == "low":
        line += " ⚠ unclear"
    return line


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def _frontmatter(fields: dict) -> str:
    lines = ["---"]
    for key, value in fields.items():
        if isinstance(value, list):
            value = "[" + ", ".join(value) + "]"
        lines.append(f"{key}: {value}")
    return "\n".join(lines + ["---", ""])


def _replace_block(text: str, start: str, end: str, block: str) -> str:
    pattern = re.compile(re.escape(start) + r".*?" + re.escape(end), re.DOTALL)
    if pattern.search(text):
        return pattern.sub(lambda _: block, text)
    return text.rstrip("\n") + "\n\n" + block + "\n"


class WikiWriter:
    def __init__(self, cfg, store):
        self.cfg = cfg
        self.store = store
        self.wiki = cfg.wiki_dir

    def _source_link(self, pdf_path: str, page_no: int, from_dir: Path) -> str:
        rel = os.path.relpath(pdf_path, from_dir)
        return f"<{rel}#page={page_no}>"

    def write(self, today: str, report) -> None:
        pages = self.store.pages(WIKI_KINDS)
        entries = self.store.entries("p.kind != 'one_on_one'")
        days = self._write_journal_days(pages, entries, today)
        decisions = [e for e in entries if e["bullet"] == "decision"]
        self._write_decision_log(decisions, today)
        self._write_signals([e for e in entries if e["signal"]], today)
        self._write_project_blocks(decisions)
        self._write_index(days, entries, today)
        self._append_log(report, today)

    def _write_journal_days(self, pages: list[dict], entries: list[dict], today: str) -> list[str]:
        out_dir = self.wiki / "journal"
        out_dir.mkdir(parents=True, exist_ok=True)
        pages_by_day: dict[str, list[dict]] = defaultdict(list)
        for p in pages:
            pages_by_day[p["date"] or "undated"].append(p)
        entries_by_day: dict[str, list[dict]] = defaultdict(list)
        for e in entries:
            entries_by_day[e["date"] or "undated"].append(e)

        for day, day_pages in pages_by_day.items():
            events = {}
            for p in day_pages:
                for ev in json.loads(p["events_json"]):
                    events.setdefault(ev["title"], ev)
            sections: OrderedDict[str, list[str]] = OrderedDict()
            for e in entries_by_day[day]:
                if e["bullet"] == "event":
                    sections.setdefault(e["text"], [])
                    continue
                sections.setdefault(e["meeting"] or "Notes", []).append(format_entry(e))
            projects = sorted({e["project"] for e in entries_by_day[day] if e["project"]})
            body = [
                _frontmatter(
                    {
                        "type": "journal",
                        "tags": ["journal", *projects],
                        "date_added": day,
                        "date_updated": today,
                        "sources": sorted({os.path.relpath(p["pdf_path"], self.cfg.wiki_root) for p in day_pages}),
                        "status": "active",
                    }
                ),
                f"# Journal: {day}",
                "",
                GENERATED,
                "",
            ]
            for title, lines in sections.items():
                body.append(f"## {title}")
                ev = events.get(title)
                if ev:
                    body.append(f"○ {ev['time'] or ''} · {' '.join(ev['people'])}".replace("○  ·", "○ ·"))
                body.append("")
                body.extend(f"- {line}" for line in lines)
                body.append("")
            body.append("## Sources")
            for p in day_pages:
                body.append(
                    f"- [{p['notebook']}, page {p['page_no']}]({self._source_link(p['pdf_path'], p['page_no'], out_dir)})"
                )
            body.append("")
            for p in day_pages:
                body.append(f"> [!note]- Transcription: {p['notebook']}, page {p['page_no']}")
                body.extend(f"> {line}" for line in p["transcription"].splitlines())
                body.append("")
            body.append("Related: [[decision-log]] · [[signals]]")
            (out_dir / f"{day}.md").write_text("\n".join(body) + "\n")
        return sorted(pages_by_day, reverse=True)

    def _write_decision_log(self, decisions: list[dict], today: str) -> None:
        rows = ["| Date | Decision | Project | Source |", "|------|----------|---------|--------|"]
        for e in sorted(decisions, key=lambda e: e["date"] or "", reverse=True):
            project = f"[[{e['project']}]]" if e["project"] else "—"
            day = e["date"] or "undated"
            rows.append(f"| {day} | {_cell(e['text'])} | {project} | [[{day}]] |")
        self._write_insight(
            "decision-log", "Decision log", "Every △ decision from the journal, newest first.", rows, today
        )

    def _write_signals(self, signals: list[dict], today: str) -> None:
        rows = [
            f"- {e['date'] or 'undated'} · {_cell(e['text'])} ([[{e['date'] or 'undated'}]])"
            for e in sorted(signals, key=lambda e: e["date"] or "", reverse=True)
        ]
        self._write_insight(
            "signals",
            "Signals",
            "Every ! signal from the journal, newest first. The daily digest groups repeats.",
            rows,
            today,
        )

    def _write_insight(self, name: str, title: str, intro: str, rows: list[str], today: str) -> None:
        out = self.wiki / "insights"
        out.mkdir(parents=True, exist_ok=True)
        text = "\n".join(
            [
                _frontmatter({"type": "insight", "tags": ["journal"], "date_updated": today, "status": "active"}),
                f"# {title}",
                "",
                GENERATED,
                "",
                intro,
                "",
                *rows,
                "",
            ]
        )
        (out / f"{name}.md").write_text(text)

    def _write_project_blocks(self, decisions: list[dict]) -> None:
        by_project: dict[str, list[dict]] = defaultdict(list)
        for e in decisions:
            if e["project"]:
                by_project[e["project"]].append(e)
        for project, items in by_project.items():
            path = self.wiki / "projects" / f"{project}.md"
            if not path.exists():
                continue
            lines = [f"- {e['date'] or 'undated'}: {e['text']} ([[{e['date'] or 'undated'}]])" for e in items]
            block = "\n".join([PROJECT_START, "## Decisions from meetings", "", *lines, PROJECT_END])
            path.write_text(_replace_block(path.read_text(), PROJECT_START, PROJECT_END, block))

    def _write_index(self, days: list[str], entries: list[dict], today: str) -> None:
        path = self.wiki / "index.md"
        counts: dict[str, dict[str, int]] = defaultdict(lambda: {"decision": 0, "task": 0})
        for e in entries:
            if e["bullet"] in ("decision", "task"):
                counts[e["date"] or "undated"][e["bullet"]] += 1
        rows = [f"| [[{d}]] | {counts[d]['decision']} | {counts[d]['task']} |" for d in days]
        block = "\n".join(
            [
                INDEX_START,
                "## Journal",
                "Generated by journal-kb. See [[decision-log]], [[signals]] and [[digest]].",
                "",
                "| Page | Decisions | Tasks |",
                "|------|-----------|-------|",
                *rows,
                INDEX_END,
            ]
        )
        text = path.read_text() if path.exists() else "# Wiki Index\n"
        text = re.sub(r"^date_updated: .*$", f"date_updated: {today}", text, count=1, flags=re.MULTILINE)
        text = re.sub(r"Last updated: \d{4}-\d{2}-\d{2}", f"Last updated: {today}", text, count=1)
        path.write_text(_replace_block(text, INDEX_START, INDEX_END, block))

    def _append_log(self, report, today: str) -> None:
        path = self.wiki / "log.md"
        header = "# Wiki Activity Log\n\n"
        text = path.read_text() if path.exists() else header
        notebooks = ", ".join(sorted(report.notebooks)) or "none"
        entry = (
            f"## [{today}] ingest | journal | {report.pages_read} pages read, {report.pages_deleted} removed\n"
            f"- Notebooks: {notebooks}. Unchanged pages skipped: {report.pages_skipped}.\n"
            f"- Tokens: {report.input_tokens} in / {report.output_tokens} out. Errors: {len(report.errors)}.\n"
            f"- Regenerated `wiki/journal/`, [[decision-log]], [[signals]] and the Journal block in `index.md`.\n\n"
        )
        if text.startswith(header):
            text = header + entry + text[len(header) :]
        else:
            text = entry + text
        path.write_text(text)
